package com.bank.recon;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.*;

public class TwoSumDemo {
    private static final Logger log = Logger.getLogger(TwoSumDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReconciliationService svc = new ReconciliationService();

        // Rajesh's sorted debits in paise (sorted ascending)
        long[] debits = {10_000L, 25_000L, 40_000L, 65_000L, 90_000L};

        int[] hit = svc.findMatchingPair(debits, 65_000L); // 25000 + 40000
        log.info(() -> "Pair indexes for 650.00: " + Arrays.toString(hit)
                + " = " + paiseToRupees(debits[hit[0]]) + " + " + paiseToRupees(debits[hit[1]]));

        int[] miss = svc.findMatchingPair(debits, 1L);
        log.info(() -> "Pair indexes for 0.01: " + Arrays.toString(miss));
    }

    static BigDecimal paiseToRupees(long paise) {
        return BigDecimal.valueOf(paise).movePointLeft(2);
    }
}

