class ReconciliationService {
    private static final Logger log = Logger.getLogger(ReconciliationService.class.getName());

    // Opposite-end two pointers. Input MUST be sorted ascending. O(n), O(1).
    int[] findMatchingPair(long[] sortedPaise, long targetPaise) {
        int left = 0, right = sortedPaise.length - 1;
        while (left < right) {
            long sum = sortedPaise[left] + sortedPaise[right]; // long avoids overflow
            if (sum == targetPaise) {
                log.info(() -> "Match at indexes " + left + "," + right);
                return new int[]{left, right};
            } else if (sum < targetPaise) {
                left++;  // smallest value too small → discard it
            } else {
                right--; // largest value too big → discard it
            }
        }
        log.warning(() -> "No pair sums to target " + targetPaise + " paise");
        return new int[]{-1, -1};
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
